package local.quickpic.tapprobe;
import android.app.*;import android.content.*;import android.os.*;import android.graphics.*;import android.net.Uri;import android.preference.PreferenceManager;import android.view.*;import android.view.accessibility.AccessibilityNodeInfo;import java.io.*;import java.lang.reflect.*;import java.util.concurrent.*;import org.json.*;
/** Measures the real viewer callback and new-image draw; no app implementation is copied. */
public final class TimingProbe extends Instrumentation {
 Context target;Activity activity;View picture;Object controller;Field listenerField,bitmapField;Method indexMethod;JSONArray samples=new JSONArray();Bundle args;final int[] colors={0xffcc4444,0xff44aa44,0xff4477cc,0xffbbbb44,0xff994499};
 @Override public void onCreate(Bundle b){super.onCreate(b);args=b;start();}
 View find(View v){if(v.getClass().getName().equals("com.alensw.ui.view.PictureView"))return v;if(v instanceof ViewGroup)for(int i=0;i<((ViewGroup)v).getChildCount();i++){View r=find(((ViewGroup)v).getChildAt(i));if(r!=null)return r;}return null;}
 int index()throws Exception{return(Integer)indexMethod.invoke(controller);}
 boolean near(int a,int b){return Math.abs(Color.red(a)-Color.red(b))<12&&Math.abs(Color.green(a)-Color.green(b))<12&&Math.abs(Color.blue(a)-Color.blue(b))<12;}
 void prefs(){runOnMainSync(()->PreferenceManager.getDefaultSharedPreferences(target).edit().putBoolean("reader_mode",false).putInt("eink_render_mode",0).putBoolean("single_tap_zoom",false).putInt("tap_page_layout",1).putBoolean("tap_page_reverse",false).commit());}
 void send(long d,int action,float x,float y){MotionEvent e=MotionEvent.obtain(d,SystemClock.uptimeMillis(),action,x,y,0);e.setSource(InputDevice.SOURCE_TOUCHSCREEN);try{sendPointerSync(e);}finally{e.recycle();}}
 void fixtures()throws Exception{File folder=new File(Environment.getExternalStoragePublicDirectory(Environment.DIRECTORY_PICTURES),"QuickPicTapTest");folder.mkdirs();for(int i=0;i<5;i++){File f=new File(folder,"page-0"+(i+1)+".png");if(f.exists())continue;Bitmap b=Bitmap.createBitmap(360,640,Bitmap.Config.ARGB_8888);b.eraseColor(colors[i]);try(FileOutputStream o=new FileOutputStream(f)){b.compress(Bitmap.CompressFormat.PNG,100,o);}b.recycle();}}
 String labels(AccessibilityNodeInfo n){if(n==null)return "null";String s="["+n.getText()+"|"+n.getContentDescription()+"]";for(int i=0;i<n.getChildCount();i++)s+=labels(n.getChild(i));return s;}
 void hide(){runOnMainSync(()->{try{Class<?> c=target.getClassLoader().loadClass("com.alensw.ui.activity.ao");c.getDeclaredMethod("a",boolean.class).invoke(activity,false);}catch(Exception e){throw new RuntimeException(e);}});waitForIdleSync();SystemClock.sleep(60);}
 JSONObject trial(int press)throws Exception{
  hide();final int[] base={0};runOnMainSync(()->{try{base[0]=index();}catch(Exception e){throw new RuntimeException(e);}});final int expected=(base[0]+1)%5;
  final long[] time=new long[6];final CountDownLatch complete=new CountDownLatch(1);final boolean[] pending={false};Object original=listenerField.get(picture);Class<?> q=listenerField.getType();
  Object proxy=Proxy.newProxyInstance(q.getClassLoader(),new Class<?>[]{q},(o,m,a)->{boolean turn=m.getName().equals("b")&&a!=null&&a.length==1&&a[0] instanceof Integer;if(turn&&time[2]==0)time[2]=SystemClock.uptimeMillis();try{return m.invoke(original,a);}catch(InvocationTargetException e){throw e.getCause();}finally{if(turn)time[3]=SystemClock.uptimeMillis();}});
  ViewTreeObserver.OnDrawListener draw=()->{try{if(!pending[0]&&time[2]>0&&index()==expected){Object p=bitmapField.get(picture);if(p!=null){Bitmap b=(Bitmap)p.getClass().getMethod("d").invoke(p);if(b!=null&&!b.isRecycled()&&near(b.getPixel(0,0),colors[expected])){pending[0]=true;time[4]=SystemClock.uptimeMillis();picture.getViewTreeObserver().registerFrameCommitCallback(()->{time[5]=SystemClock.uptimeMillis();complete.countDown();});}}}}catch(Exception ignored){}};
  runOnMainSync(()->{try{listenerField.set(picture,proxy);picture.getViewTreeObserver().addOnDrawListener(draw);}catch(Exception e){throw new RuntimeException(e);}});
  int[] location=new int[2];picture.getLocationInWindow(location);float x=location[0]+picture.getWidth()*.88f,y=location[1]+picture.getHeight()*.82f;
  time[0]=SystemClock.uptimeMillis();send(time[0],MotionEvent.ACTION_DOWN,x,y);SystemClock.sleep(press);time[1]=SystemClock.uptimeMillis();send(time[0],MotionEvent.ACTION_UP,x,y);
  boolean done=complete.await(2,TimeUnit.SECONDS);runOnMainSync(()->{picture.getViewTreeObserver().removeOnDrawListener(draw);try{listenerField.set(picture,original);}catch(Exception e){throw new RuntimeException(e);}});
  JSONObject r=new JSONObject().put("press_ms",press).put("down_to_up_ms",time[1]-time[0]).put("up_to_turn_ms",time[2]==0?-1:time[2]-time[1]).put("turn_callback_ms",time[3]-time[2]).put("turn_to_new_draw_ms",time[4]==0?-1:time[4]-time[2]).put("draw_to_frame_commit_ms",time[5]==0?-1:time[5]-time[4]).put("up_to_frame_commit_ms",time[5]==0?-1:time[5]-time[1]).put("frame_committed",done).put("base",base[0]).put("expected",expected);
  if(time[2]==0||time[4]==0)throw new Exception("No actual page turn/draw: "+r+" layout="+PreferenceManager.getDefaultSharedPreferences(target).getInt("tap_page_layout",0)+" shown="+picture.isShown()+" focus="+picture.hasWindowFocus());SystemClock.sleep(360);return r;
 }
 @Override public void onStart(){Bundle out=new Bundle();try{target=getTargetContext();prefs();fixtures();StrictMode.setVmPolicy(new StrictMode.VmPolicy.Builder().build());Intent open=new Intent(Intent.ACTION_VIEW).setClassName(target,target.getPackageName()+".GalleryActivity").setDataAndType(Uri.fromFile(new File(Environment.getExternalStoragePublicDirectory(Environment.DIRECTORY_PICTURES),"QuickPicTapTest/page-03.png")),"image/png").addFlags(Intent.FLAG_ACTIVITY_NEW_TASK|Intent.FLAG_ACTIVITY_CLEAR_TASK);activity=startActivitySync(open);waitForIdleSync();SystemClock.sleep(2000);AccessibilityNodeInfo root=getUiAutomation().getRootInActiveWindow();if(root!=null)for(AccessibilityNodeInfo n:root.findAccessibilityNodeInfosByText("Got it"))n.performAction(AccessibilityNodeInfo.ACTION_CLICK);waitForIdleSync();SystemClock.sleep(500);root=getUiAutomation().getRootInActiveWindow();if(root!=null&&!root.findAccessibilityNodeInfosByText("WiFi transfer").isEmpty()){sendKeyDownUpSync(KeyEvent.KEYCODE_BACK);waitForIdleSync();}
  prefs();picture=find(activity.getWindow().getDecorView());for(int k=0;k<4&&!picture.hasWindowFocus();k++){sendKeyDownUpSync(KeyEvent.KEYCODE_BACK);waitForIdleSync();SystemClock.sleep(300);}if(picture==null)throw new Exception("No actual PictureView");controller=activity.getClass().getMethod("c").invoke(activity);indexMethod=controller.getClass().getMethod("readerIndex");Class<?> view=target.getClassLoader().loadClass("com.alensw.ui.view.j");listenerField=view.getDeclaredField("K");listenerField.setAccessible(true);bitmapField=view.getDeclaredField("b");bitmapField.setAccessible(true);
  for(int i=0;i<6;i++)trial(60); // Warm all five tiny pages before reporting latency.
  for(int press:new int[]{60,160})for(int i=0;i<5;i++)samples.put(trial(press));
  int slow=0;for(int i=0;i<samples.length();i++)if(samples.getJSONObject(i).getInt("press_ms")==60&&samples.getJSONObject(i).getLong("up_to_turn_ms")>=100)slow++;
  boolean fast=slow==0;JSONObject r=new JSONObject().put("version",target.getPackageManager().getPackageInfo(target.getPackageName(),0).versionName).put("double_tap_timeout_ms",ViewConfiguration.getDoubleTapTimeout()).put("reader_mode",false).put("eink_mode",0).put("samples",samples).put("short_tap_slow_samples",slow).put("fast_tap_check",fast?"PASS":"FAIL").put("measurements_complete",true).put("input_scope","Instrumentation.sendPointerSync;frame commit is submitted GPU frame,not physical screen scanout");out.putString("stream",r.toString()+"\n");finish(fast?0:1,out);
 }catch(Throwable e){StringWriter s=new StringWriter();e.printStackTrace(new PrintWriter(s));out.putString("stream",s.toString());finish(2,out);}}
}
